@SpringBootApplication
public class OrderServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrderServiceApplication.class, args);
    }
}

// In pom.xml, ensure you have:
<build>
    <plugins>
        <plugin>
            <groupId>org.springframework.boot</groupId>
            <artifactId>spring-boot-maven-plugin</artifactId>
        </plugin>
    </plugins>
</build>

// Terminal command to run:
// mvn spring-boot:run

// Output shows:
// [INFO] Attaching agents: []
// Started OrderServiceApplication in 2.341 seconds

// In pom.xml:
<build>
    <plugins>
        <plugin>
            <groupId>org.springframework.boot</groupId>
            <artifactId>spring-boot-maven-plugin</artifactId>
            <version>3.2.0</version>
            <executions>
                <execution>
                    <goals>
                        <goal>repackage</goal> <!-- Key goal that creates fat JAR -->
                    </goals>
                </execution>
            </executions>
        </plugin>
    </plugins>
</build>

// After mvn package, examine the JAR structure:
// order-service-1.0.0.jar
//   BOOT-INF/
//     classes/          <- Your compiled code
//     lib/              <- All dependency JARs
//   META-INF/
//     MANIFEST.MF       <- Points to JarLauncher
//   org/springframework/boot/loader/  <- Custom class loader

// Step 1: Package the application
// Terminal command:
// mvn clean package

// Maven output shows:
// [INFO] Building jar: target/order-service-1.0.0.jar
// [INFO] BUILD SUCCESS

// Step 2: Run the packaged application
// Terminal command:
// java -jar target/order-service-1.0.0.jar

// Application starts:
// Started OrderServiceApplication in 2.5 seconds (process running on 12345)

// Step 3: Run with custom configuration
// java -Xmx512m -jar target/order-service-1.0.0.jar --server.port=8081 --spring.profiles.active=prod

// Step 4: Run in background (Linux/Mac)
// nohup java -jar target/order-service-1.0.0.jar > app.log 2>&1 &

// Step 5: Check the running process
// ps aux | grep order-service

// Add DevTools dependency in pom.xml:
<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-devtools</artifactId>
    <scope>runtime</scope>
    <optional>true</optional>  // Prevents transitive inclusion
</dependency>

@RestController
public class CustomerController {

    @GetMapping("/customers")
    public List<String> getCustomers() {
        // Change this return value, save file, and watch DevTools restart
        return List.of("Alice", "Bob", "Charlie");
    }
}

// DevTools console output when you save a file:
// Restarting due to 1 class path change (0 additions, 0 deletions, 1 modification)
// Started CustomerApplication in 2.341 seconds (process running on 12345)

// In application.properties, customize DevTools behavior:
spring.devtools.restart.enabled=true
spring.devtools.restart.poll-interval=1s
spring.devtools.restart.quiet-period=400ms
